/* =========================================================
   ACTIVITY PHOTOS
   ========================================================= */

document.addEventListener("click", (e) => {

  /* See Photos button */
  const seePhotosBtn = e.target.closest("#see-photos");

  if (seePhotosBtn) {

    const photos = activityPhotoSets[activeStory] || [];
    const grid = $("activity-photos-grid");
    const modal = $("activity-photos-modal");

    if (!grid || !modal) return;

    grid.innerHTML = photos.map((src, index) => `
      <img
        src="${src}"
        alt="Activity photo ${index + 1}"
        class="activity-gallery-photo"
        loading="lazy"
      >
    `).join("");

    modal.classList.remove("hidden");

    if (typeof lucide !== "undefined") {
      lucide.createIcons();
    }
  }


  /* Close button */
  const closeBtn = e.target.closest("#close-activity-photos");

  if (closeBtn) {

    const modal = $("activity-photos-modal");

    if (modal) {
      modal.classList.add("hidden");
    }
  }


  /* Click outside modal */
  const modal = $("activity-photos-modal");

  if (modal && e.target === modal) {
    modal.classList.add("hidden");
  }

});

/* =========================================================
   FULL SCREEN ACTIVITY PHOTO VIEWER
   ========================================================= */

let currentViewerPhotos = [];
let currentViewerIndex = 0;


/* Open selected photo */

function openPhotoViewer(photos, index) {
  const viewer = document.getElementById("activity-photo-viewer");
  const image = document.getElementById("photo-viewer-image");
  const counter = document.getElementById("photo-viewer-counter");

  if (!viewer || !image || !counter || !photos.length) return;

  currentViewerPhotos = photos;
  currentViewerIndex = index;

  image.src = currentViewerPhotos[currentViewerIndex];

  counter.textContent =
    `${currentViewerIndex + 1} / ${currentViewerPhotos.length}`;

  viewer.classList.remove("hidden");

  document.body.style.overflow = "hidden";
}


/* Close viewer */

function closePhotoViewer() {
  const viewer = document.getElementById("activity-photo-viewer");

  if (!viewer) return;

  viewer.classList.add("hidden");

  document.body.style.overflow = "";
}


/* Show next photo */

function showNextPhoto() {
  if (!currentViewerPhotos.length) return;

  currentViewerIndex =
    (currentViewerIndex + 1) % currentViewerPhotos.length;

  updateViewerImage();
}


/* Show previous photo */

function showPreviousPhoto() {
  if (!currentViewerPhotos.length) return;

  currentViewerIndex =
    (currentViewerIndex - 1 + currentViewerPhotos.length)
    % currentViewerPhotos.length;

  updateViewerImage();
}


/* Update displayed image */

function updateViewerImage() {
  const image = document.getElementById("photo-viewer-image");
  const counter = document.getElementById("photo-viewer-counter");

  if (!image || !counter) return;

  image.src = currentViewerPhotos[currentViewerIndex];

  counter.textContent =
    `${currentViewerIndex + 1} / ${currentViewerPhotos.length}`;
}


/* =========================================================
   GALLERY PHOTO CLICK
   ========================================================= */

document.addEventListener("click", (e) => {

  const photo = e.target.closest(".activity-gallery-photo");

  if (!photo) return;

  const grid = document.getElementById("activity-photos-grid");

  if (!grid) return;

  const photos = Array.from(
    grid.querySelectorAll(".activity-gallery-photo")
  ).map(img => img.src);

  const index = Array.from(
    grid.querySelectorAll(".activity-gallery-photo")
  ).indexOf(photo);

  openPhotoViewer(photos, index);
});


/* =========================================================
   VIEWER BUTTONS
   ========================================================= */

document.addEventListener("click", (e) => {

  if (e.target.closest("#close-photo-viewer")) {
    closePhotoViewer();
    return;
  }

  if (e.target.closest("#photo-viewer-next")) {
    showNextPhoto();
    return;
  }

  if (e.target.closest("#photo-viewer-prev")) {
    showPreviousPhoto();
    return;
  }

  /* Close when clicking the dark background */

  const viewer = document.getElementById("activity-photo-viewer");

  if (
    viewer &&
    e.target === viewer
  ) {
    closePhotoViewer();
  }
});


/* =========================================================
   KEYBOARD CONTROLS
   ========================================================= */

document.addEventListener("keydown", (e) => {

  const viewer = document.getElementById("activity-photo-viewer");

  if (!viewer || viewer.classList.contains("hidden")) return;

  if (e.key === "ArrowRight") {
    showNextPhoto();
  }

  if (e.key === "ArrowLeft") {
    showPreviousPhoto();
  }

  if (e.key === "Escape") {
    closePhotoViewer();
  }
});
