    // Initialize hero carousel with dynamic image loading
    function initHeroCarousel(){
      const track=$("carousel-track");
      const heroImages=[
        "images/hero/hero-001.jpeg",
        "images/hero/hero-004.jpeg",
        "images/hero/hero-008.jpeg",
        "images/hero/hero-012.jpeg",
        "images/hero/hero-032.jpeg",
        "images/hero/hero-037.jpeg",
        "images/hero/hero-042.jpeg",
        "images/hero/hero-054.jpeg",
        "images/hero/hero-057.jpeg",
        "images/hero/hero-061.jpeg",
        "images/hero/hero-065.jpeg"
      ];

      // Create carousel slides dynamically
      track.innerHTML=heroImages.map((src,idx)=>`
        <div class="carousel-slide ${idx===0?'active':''}">
          <img src="${src}" alt="Dwarkamai Sanstha activity photo ${idx+1}" class="carousel-img">
        </div>
      `).join("");
    }

    // Call on page load to generate slides before initCarousel
    window.addEventListener("DOMContentLoaded",initHeroCarousel,{once:true});

    function initCarousel(){
      const slides=[...document.querySelectorAll(".carousel-slide")];
      const dots=$("carousel-dots");
      const prev=$("carousel-prev");
      const next=$("carousel-next");
      const root=$("home-carousel");
      if(!slides.length||!dots) return;
      dots.innerHTML=slides.map((_,n)=>`<button type="button" aria-label="Slide ${n+1}" class="${n===0?"active":""}"></button>`).join("");
      let i=0, timer;
      const show=n=>{ i=(n+slides.length)%slides.length; slides.forEach((s,idx)=>s.classList.toggle("active",idx===i)); dots.querySelectorAll("button").forEach((d,idx)=>d.classList.toggle("active",idx===i)); };
      const restart=()=>{ clearInterval(timer); timer=setInterval(()=>show(i+1),5500); };
      dots.addEventListener("click",e=>{ const b=e.target.closest("button"); if(!b) return; show([...dots.querySelectorAll("button")].indexOf(b)); restart(); });
      if(prev) prev.addEventListener("click",()=>{ show(i-1); restart(); });
      if(next) next.addEventListener("click",()=>{ show(i+1); restart(); });
      let startX=0;
      if(root){
        root.addEventListener("touchstart",e=>{ startX=e.changedTouches[0].screenX; },{passive:true});
        root.addEventListener("touchend",e=>{ const dx=e.changedTouches[0].screenX-startX; if(Math.abs(dx)>40){ show(dx<0?i+1:i-1); restart(); }},{passive:true});
      }
      restart();
    }
    // ═══════════════════════════════════════════════════════════════
    // SCROLL ANIMATION OBSERVER - Fade-in effects on scroll
    // ═══════════════════════════════════════════════════════════════
    function initScrollAnimations(){
      const observer=new IntersectionObserver((entries)=>{
        entries.forEach(entry=>{
          if(entry.isIntersecting){
            entry.target.style.animation="scrollFadeIn 0.7s ease forwards";
            entry.target.style.opacity="1";
            observer.unobserve(entry.target);
          }
        });
      },{ threshold:0.1, rootMargin:"0px 0px -50px 0px" });

      // Observe all cards, articles, and sections
      document.querySelectorAll(".soft-card, article:not(.activity-detail), .work-card, .project-tile, .credentials-band, section[class*='mb-'], .timeline-item").forEach(el=>{
        el.style.opacity="0";
        observer.observe(el);
      });
    }

    // ═══════════════════════════════════════════════════════════════
    // STAGGER ANIMATIONS - Cards appear in sequence
    // ═══════════════════════════════════════════════════════════════
    function initStaggerAnimations(){
      const cardGroups=document.querySelectorAll("#activity-cards, #committee-grid, #gallery-grid");
      cardGroups.forEach((group,groupIdx)=>{
        const cards=group.querySelectorAll("article");
        cards.forEach((card,idx)=>{
          card.style.animation=`cardStagger 0.6s ease backwards`;
          card.style.animationDelay=`${idx*0.1}s`;
        });
      });
    }

    // ═══════════════════════════════════════════════════════════════
    // HOVER ANIMATIONS - Enhanced interactivity
    // ═══════════════════════════════════════════════════════════════
    function initHoverAnimations(){
      document.querySelectorAll(".soft-card, .work-card, .project-tile").forEach(el=>{
        el.classList.add("hover-lift");
        el.addEventListener("mouseenter",function(){
          this.style.transform="translateY(-8px)";
          this.style.boxShadow="0 12px 24px rgba(18, 59, 120, 0.2)";
        });
        el.addEventListener("mouseleave",function(){
          this.style.transform="translateY(0)";
          this.style.boxShadow="";
        });
      });
    }

    // ═══════════════════════════════════════════════════════════════
    // PAGE TRANSITION ANIMATIONS
    // ═══════════════════════════════════════════════════════════════
    function addPageTransitions(){
      document.querySelectorAll(".page-section").forEach(section=>{
        section.addEventListener("animationend",()=>{
          // Trigger animations for child elements
          section.querySelectorAll(".soft-card, article, .work-card").forEach((el,idx)=>{
            el.style.animation=`scrollFadeIn 0.6s ease forwards`;
            el.style.animationDelay=`${idx*0.05}s`;
          });
        });
      });
    }

    // Initialize all animations after page load
    window.addEventListener("DOMContentLoaded",()=>{
      applyLanguage(currentLang);
      navigate(location.hash||"#home");
      lucide.createIcons();
      initCarousel();

      // Schedule animation initialization slightly after DOM is ready
      setTimeout(()=>{
        initScrollAnimations();
        initStaggerAnimations();
        initHoverAnimations();
        addPageTransitions();
      },100);
    });
  
